<script>const checks=[...document.querySelectorAll('.choose')],quantities=[...document.querySelectorAll('.qty')],total=document.getElementById('liveTotal'),subtotal=document.getElementById('subtotal'),lines=document.getElementById('lineCount'),ticket=document.getElementById('ticketLines');function money(n){return Number(n).toFixed(2)}function quantityLabel(n){return new Intl.NumberFormat('es-BO',{maximumFractionDigits:3}).format(n)}function escapeHTML(value){const entities={'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'};return String(value).replace(/[&<>"']/g,char=>entities[char])}function refresh(){let sum=0,count=0,html='';quantities.forEach((q,i)=>{if(q.dataset.decimal==='0'&&Number(q.value)%1!==0){q.setCustomValidity('Este producto solo permite cantidades enteras.')}else{q.setCustomValidity('')}const quantity=Number(q.value||0),price=Number(q.dataset.price),check=checks[i];if(quantity>0&&check.checked){const line=quantity*price;sum+=line;count++;html+='<div class="ticket-line"><span>'+escapeHTML(check.dataset.name)+'<br><small>'+quantityLabel(quantity)+' / '+quantityLabel(Number(q.max||0))+' '+escapeHTML(q.dataset.unit)+' disponibles · Bs '+money(price)+' / '+escapeHTML(q.dataset.unit)+'</small></span><span>Bs '+money(line)+'</span></div>'}check.closest('.pos-item').classList.toggle('selected',check.checked)});subtotal.textContent=money(sum);total.textContent=money(sum);lines.textContent=count+' ítem'+(count===1?'':'s');ticket.innerHTML=html||'<div class="empty-ticket">Seleccione productos para la venta.</div>'}checks.forEach((c,i)=>c.addEventListener('change',()=>{const q=quantities[i];q.disabled=!c.checked;q.value=c.checked&&Number(q.value)===0?1:(!c.checked?0:q.value);refresh()}));quantities.forEach(q=>q.addEventListener('input',refresh));document.getElementById('productFilter').addEventListener('input',e=>{document.querySelectorAll('.pos-item').forEach(item=>item.hidden=!item.dataset.name.includes(e.target.value.toLowerCase()));const visible=document.querySelectorAll('.pos-item:not([hidden])').length;document.getElementById('productCount').textContent='Mostrando '+visible+' / '+checks.length+' productos'});</script>
